.chat-hist-pop { position: absolute; top: calc(100% + 4px); right: 0; width: 280px; max-height: 60vh; overflow-y: auto; background: var(--panel); border: 1px solid var(--border); border-radius: 8px; box-shadow: var(--shadow); z-index: 90; padding: 4px; }
