// ---------- 对话历史（localStorage 存档，新对话不再丢旧的）----------
_loadStore() { try { const a = JSON.parse(localStorage.getItem(this._histKey) || '[]'); return Array.isArray(a) ? a : []; } catch { return []; } },
_saveStore(list) { try { localStorage.setItem(this._histKey, JSON.stringify(list.slice(0, this._histMax))); } catch { /* 配额满则静默 */ } },
_curTitle() {
  const u = $('#chat-messages .chat-msg.user .chat-bubble');
  const t = (u ? u.textContent : '').trim().replace(/\s+/g, ' ');
  return t ? t.slice(0, 40) : '未命名对话';
},
_hasMessages() { return !!$('#chat-messages .chat-msg'); },
// 把当前对话写回历史库（有消息才存）；返回是否存了
_persistCurrent() {
  if (!this._hasMessages()) return false;
  if (!this.curId) this.curId = 'c' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  const list = this._loadStore();
  const entry = {
    id: this.curId, backend: this.backend, sessionId: this.sessionId,
    history: this.history.slice(), cursorModel: this.cursorModel, cursorMode: this.cursorMode,
    title: this._curTitle(), updated: Date.now(), html: $('#chat-messages').innerHTML,
  };
  const i = list.findIndex((x) => x.id === this.curId);
  if (i >= 0) list[i] = entry; else list.unshift(entry);
  list.sort((a, b) => b.updated - a.updated);
  this._saveStore(list);
  return true;
},
newChat() {
  this._persistCurrent();
  this.curId = ''; this.sessionId = ''; this.history = []; this.attachments = [];
  this.renderChips(); $('#chat-messages').innerHTML = ''; this.renderEmpty();
  $('#chat-history-pop').classList.add('hidden');
},
toggleHistoryPop() {
  const pop = $('#chat-history-pop'); if (!pop) return;
  if (pop.classList.contains('hidden')) { this._persistCurrent(); this.renderHistory(); pop.classList.remove('hidden'); }
  else pop.classList.add('hidden');
},
renderHistory() {
  const pop = $('#chat-history-pop'); if (!pop) return;
  const list = this._loadStore();
  if (!list.length) { pop.innerHTML = '<div class="chat-hist-empty">还没有历史对话<br>开新对话后，旧的会存到这里</div>'; return; }
  const label = { cursor: 'Cursor', api: 'API', codex: 'Codex' };
  pop.innerHTML = list.map((s) => `<div class="chat-hist-item${s.id === this.curId ? ' cur' : ''}" data-id="${this.esc(s.id)}"><div class="chat-hist-main"><div class="chat-hist-title">${this.esc(s.title || '未命名对话')}</div><div class="chat-hist-meta">${label[s.backend] || s.backend} · ${fmtTimeAgo(s.updated)}</div></div><span class="chat-hist-del" data-del="${this.esc(s.id)}" title="删除">✕</span></div>`).join('');
  pop.querySelectorAll('.chat-hist-item').forEach((el) => { el.onclick = (e) => { if (e.target.closest('.chat-hist-del')) return; this.restoreSession(el.dataset.id); }; });
  pop.querySelectorAll('.chat-hist-del').forEach((x) => { x.onclick = (e) => { e.stopPropagation(); this.deleteSession(x.dataset.del); }; });
},
restoreSession(id) {
  if (id === this.curId) { $('#chat-history-pop').classList.add('hidden'); return; }
  this._persistCurrent();
  const s = this._loadStore().find((x) => x.id === id); if (!s) return;
  this.curId = s.id;
  this.backend = s.backend || 'cursor';
  this.sessionId = s.sessionId || '';
  this.history = Array.isArray(s.history) ? s.history.slice() : [];
  this.cursorModel = s.cursorModel || '';
  this.cursorMode = s.cursorMode || '';
  this.attachments = []; this.renderChips();
  const sel = $('#chat-backend'); if (sel) sel.value = this.backend;
  const cd = $('#chat-cursor-mode'); if (cd) cd.value = this.cursorMode;
  this.updateBackendUI(); this.updateModelLabel(); this.refreshStatus();
  $('#chat-messages').innerHTML = s.html || '';
  $('#chat-history-pop').classList.add('hidden');
  this.scroll();
},
deleteSession(id) {
  const list = this._loadStore().filter((x) => x.id !== id);
  this._saveStore(list);
  if (id === this.curId) { this.curId = ''; this.sessionId = ''; this.history = []; $('#chat-messages').innerHTML = ''; this.renderEmpty(); }
  this.renderHistory();
},

$('#chat-new').onclick = () => chat.newChat();
$('#chat-history').onclick = (e) => { e.stopPropagation(); chat.toggleHistoryPop(); };
document.addEventListener('click', (e) => { const w = $('#chat-history-wrap'); if (w && !w.contains(e.target)) $('#chat-history-pop').classList.add('hidden'); });

