// 临时验证：复刻 app.js 里 _loadStore/_saveStore/_persistCurrent 的纯存储逻辑（去 DOM）
const mem = {};
const localStorage = { getItem: (k) => (k in mem ? mem[k] : null), setItem: (k, v) => { mem[k] = String(v); } };
const KEY = 'fb_chat_sessions', MAX = 50;

function load() { try { const a = JSON.parse(localStorage.getItem(KEY) || '[]'); return Array.isArray(a) ? a : []; } catch { return []; } }
function save(list) { try { localStorage.setItem(KEY, JSON.stringify(list.slice(0, MAX))); } catch { } }
// 复刻 _persistCurrent 的 upsert 段
function persist(entry) {
  const list = load();
  const i = list.findIndex((x) => x.id === entry.id);
  if (i >= 0) list[i] = entry; else list.unshift(entry);
  list.sort((a, b) => b.updated - a.updated);
  save(list);
}

let ok = true;
const assert = (c, m) => { if (!c) { ok = false; console.log('FAIL:', m); } else console.log('PASS:', m); };

// 1) 首存
persist({ id: 'a', title: '甲', backend: 'cursor', updated: 100 });
assert(load().length === 1 && load()[0].title === '甲', '首条写入');

// 2) 同 id 再存 = 更新而非新增
persist({ id: 'a', title: '甲改', backend: 'cursor', updated: 200 });
assert(load().length === 1 && load()[0].title === '甲改', '同 id upsert 不新增');

// 3) 新 id 新增，且按 updated 倒序
persist({ id: 'b', title: '乙', backend: 'api', updated: 300 });
assert(load().length === 2 && load()[0].id === 'b' && load()[1].id === 'a', '新增并按时间倒序');

// 4) 上限截断到 50
for (let n = 0; n < 60; n++) persist({ id: 'x' + n, title: 't' + n, backend: 'cursor', updated: 1000 + n });
assert(load().length === 50, '超过上限截断到 50');
assert(load()[0].updated >= load()[49].updated, '截断后仍倒序（保留最新）');

// 5) 删除
const after = load().filter((x) => x.id !== load()[0].id);
save(after);
assert(load().length === 49, '删除后数量减一');

console.log(ok ? '\nALL_PASS' : '\nSOME_FAIL');
process.exit(ok ? 0 : 1);

