    $('#dt-send-agent').onclick = () => this.sendToAgent();
    $('#dt-open-ext').onclick = () => this.openExternal();
    $('#dt-search-input').addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); this.search(e.target.value); } });
    this.initResizer();
  },
  initResizer() {
    const rz = $('#dt-resizer'); const sb = $('#dt-sidebar'); if (!rz || !sb) return;
    let dragging = false;
    rz.addEventListener('mousedown', (e) => { dragging = true; rz.classList.add('dragging'); e.preventDefault(); });
    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      const w = Math.max(180, Math.min(480, e.clientX - sb.getBoundingClientRect().left));
      sb.style.width = w + 'px';
    });
    window.addEventListener('mouseup', () => { if (dragging) { dragging = false; rz.classList.remove('dragging'); } });
  },
};
dingtalk.init();

