// ---------- 钉钉在线文档面板：直接嵌钉钉文档 Web 界面，原生导航 ----------
// 进面板即落到钉钉文档首页，用户在 webview 内自己点；标题随 webview 自动同步，
// 「甩给对话」跟随 webview 当前打开的文档（从地址解析 nodeId，后台用 dws 拉 markdown）。
const dingtalk = {
  HOME_URL: 'https://alidocs.dingtalk.com/',
  cur: null,   // 当前文档 { nodeId, name, docUrl }
  curMd: '',   // 当前文档 markdown（甩给 agent 用）
  webview: null,
  loaded: false,

  isOpen() { return !$('#dingtalk-panel').classList.contains('hidden'); },
  toggle() { this.isOpen() ? this.close() : this.open(); },
  open() {
    if (term.maximized) term.toggleMax(false);
    $('#main-body').classList.add('dt-open');
    $('#dingtalk-panel').classList.remove('hidden');
    $('#dingtalk-entry').classList.add('active');
    if (!this.loaded) this.mount();
  },
  close() {
    $('#main-body').classList.remove('dt-open');
    $('#dingtalk-panel').classList.add('hidden');
    $('#dingtalk-entry').classList.remove('active');
  },

  esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); },

  // 统一收口后端返回：runDws 包成 {ok,data}；业务错误是 {ok:false,error}
  async api(path) {
    try {
      const r = await (await fetch(path)).json();
      if (r && r.ok === false) return { ok: false, error: r.error || '调用失败' };
      return (r && r.data !== undefined) ? { ok: true, data: r.data } : { ok: true, data: r };
    } catch (e) { return { ok: false, error: e.message }; }
  },

  // 首次进入：桌面版挂 webview 嵌钉钉首页；网页版没有内嵌浏览器，给提示
  mount() {
    const body = $('#dt-doc-body');
    const desktop = !!(window.fanboxEnv && window.fanboxEnv.isDesktopApp);
    if (!desktop) {
      body.innerHTML = '<div class="dt-empty">钉钉在线文档需在桌面版打开<br><span style="font-size:11.5px">网页版没有内嵌浏览器</span></div>';
      this.loaded = true;
      return;
    }
    body.innerHTML = '';
    const wv = document.createElement('webview');
    wv.setAttribute('partition', 'persist:dingtalk'); // 登录态按 partition 持久化，首次需在 webview 内登录
    wv.setAttribute('allowpopups', '');
    wv.src = this.HOME_URL;
    this.webview = wv;
    body.appendChild(wv);
    wv.addEventListener('page-title-updated', (e) => this.onTitle(e.title));
    wv.addEventListener('did-navigate', (e) => this.onNavigate(e.url));
    wv.addEventListener('did-navigate-in-page', (e) => this.onNavigate(e.url));
    this.loaded = true;
  },

  // 标题随 webview 同步（去掉「- 钉钉文档」之类的应用后缀）
  onTitle(title) {
    const t = (String(title || '').replace(/\s*[-_—|·]\s*(钉钉文档|阿里云盘|alidocs|DingTalk).*$/i, '').trim()) || String(title || '').trim() || '钉钉文档';
    if (this.cur) this.cur.name = t;
    $('#dt-doc-title').textContent = t;
  },

  // 地址变化：解析当前文档 nodeId，刷新「甩给对话」「浏览器打开」目标
  onNavigate(urlStr) {
    const httpUrl = /^https?:/.test(urlStr || '') ? urlStr : '';
    $('#dt-open-ext').disabled = !httpUrl;
    const nodeId = this.parseNodeId(urlStr);
    if (!nodeId) { this.cur = null; this.curMd = ''; $('#dt-send-agent').disabled = true; return; }
    if (this.cur && this.cur.nodeId === nodeId) { this.cur.docUrl = httpUrl; return; }
    this.cur = { nodeId, name: $('#dt-doc-title').textContent || '钉钉文档', docUrl: httpUrl };
    this.curMd = '';
    $('#dt-send-agent').disabled = true;
    this.loadMarkdown(nodeId); // 后台拉正文，拉到才点亮「甩给对话」
  },

  // 从 alidocs 地址里抠 nodeId，例：https://alidocs.dingtalk.com/i/nodes/<nodeId>?...
  parseNodeId(urlStr) {
    try {
      const u = new URL(urlStr);
      if (!/alidocs\.dingtalk\.com$/i.test(u.hostname)) return '';
      const m = u.pathname.match(/\/nodes\/([A-Za-z0-9_-]{1,128})/) || (u.pathname + u.hash).match(/\/nodes\/([A-Za-z0-9_-]{1,128})/);
      return m ? m[1] : '';
    } catch { return ''; }
  },

  async loadMarkdown(nodeId) {
    const r = await this.api('/api/dingtalk/doc?node=' + encodeURIComponent(nodeId));
    if (!this.cur || this.cur.nodeId !== nodeId) return; // 期间又切了文档
    if (r.ok && r.data && typeof r.data.markdown === 'string') {
      this.curMd = r.data.markdown;
      $('#dt-send-agent').disabled = false;
    }
  },

  goHome() { if (this.webview) this.webview.src = this.HOME_URL; },
  reload() { if (this.webview) { try { this.webview.reload(); } catch { /* */ } } },

  sendToAgent() {
    if (!this.cur) return;
    const name = this.cur.name || '钉钉文档';
    if (this.curMd) {
      chat.sendContext(this.curMd, name);
    } else {
      chat.sendContext(`（这是一篇钉钉文档，可用 dws doc read --node ${this.cur.nodeId} --content-format markdown 读取全文）\n标题：${name}\n链接：${this.cur.docUrl || ''}`, name);
    }
    toast('已甩给对话窗口，输入你的要求再发送');
  },
  openExternal() {
    const url = (this.cur && this.cur.docUrl) || (this.webview && this.webview.getURL && this.webview.getURL());
    if (url && /^https?:/.test(url)) window.open(url, '_blank');
  },

  init() {
    const btn = $('#dingtalk-entry'); if (!btn) return;
    btn.onclick = () => this.toggle();
    $('#dt-close').onclick = () => this.close();
    $('#dt-home').onclick = () => this.goHome();
    $('#dt-reload').onclick = () => this.reload();
    $('#dt-send-agent').onclick = () => this.sendToAgent();
    $('#dt-open-ext').onclick = () => this.openExternal();
  },
};
dingtalk.init();

